static const nodeone::ParamSpec kParams[] = {
    {"in_gamut", "Gamut", "The colour space the picture arrives in. On a DaVinci YRGB timeline set to DaVinci Wide Gamut this is DaVinci WG, which is the default. Get this wrong and every hue is wrong, so it is the first thing to check if the image looks off before you touch anything else.", nodeone::kParamChoice, 15.0, 0.0, 15.0, 1.0, kOpt_in_gamut, 16, 0, 0},
    {"in_oetf", "Log Curve", "The transfer curve the picture arrives in, paired with Gamut above. DaVinci Intermediate for a DaVinci WG timeline, Linear if the node is fed scene-linear. Wrong here shows up as crushed or washed contrast rather than wrong colour.", nodeone::kParamChoice, 1.0, 0.0, 9.0, 1.0, kOpt_in_oetf, 10, 0, 4},
    {"display_encoding_preset", "Output", "Choose the target display standard.", nodeone::kParamChoice, 0.0, 0.0, 5.0, 1.0, kOpt_display_encoding_preset, 6, 1, 172},
    {"tn_Lp", "Peak Nits", "Peak display luminance in nits. In SDR, the max value stays pinned at 1.0. In HDR, the max value is adjusted to match peak luminance in the HDR container.", nodeone::kParamFloat, 100.0, 100.0, 1000.0, 1.0, nullptr, 0, 1, 8},
    {"tn_gb", "HDR Grey Boost", "How much middle grey is lifted as the display peak rises above 100 nits. It does nothing at 100 nits, which is why it only matters on an HDR display: there, holding grey where SDR puts it leaves the picture looking dim against the headroom above it. 0.13 is OpenDRT's own value.", nodeone::kParamFloat, 0.13, 0.0, 1.0, 0.001, nullptr, 0, 1, 12},
    {"pt_hdr", "HDR Purity", "How much of the extra headroom on an HDR display is spent holding colour rather than lightness. Like HDR Grey Boost it does nothing at 100 nits. Higher keeps saturated highlights coloured further up; lower lets them give way to white as they do in SDR.", nodeone::kParamFloat, 0.5, 0.0, 1.0, 0.001, nullptr, 0, 1, 16},
    {"out_clamp", "Clamp To Display", "Clips the result into the range the display can actually show. Leave it ON for anything you are looking at or delivering. Turn it OFF only to pass the render on to something downstream that wants the values that fell outside - a grade, a comp, an export in a wider space - because what leaves here will then contain negatives and values above one.", nodeone::kParamBool, 1.0, 0.0, 1.0, 1.0, nullptr, 0, 1, 20},
    {"look_preset", "Look", "Each preset fits OpenDRT to a spectral simulation of one negative printed on one print stock. Stock names are trademarks of their owners, used descriptively - this is an emulation, not the stock. See TRADEMARKS.txt.", nodeone::kParamChoice, 0.0, 0.0, 7.0, 1.0, kOpt_look_preset, 8, 2, 44},
    {"look_intensity", "Look Intensity", "Dials the look in. 1 is the full preset, 0 is exactly Default. In between it interpolates every parameter, which is cleaner than a dissolve.", nodeone::kParamFloat, 1.0, 0.0, 1.0, 0.001, nullptr, 0, 2, 176},
    {"look_bypass", "Bypass Look", "Drops the look. Same as Intensity at 0: exactly the Default render, toning included.", nodeone::kParamBool, 0.0, 0.0, 1.0, 1.0, nullptr, 0, 2, 48},
    {"print_tone_sel", "Toning", "Which per-level RGB tint to apply. The first entry, Use Look Preset, takes the one that belongs to the selected look.", nodeone::kParamChoice, 0.0, 0.0, 8.0, 1.0, kOpt_print_tone_sel, 9, 3, 52},
    {"tone_intensity", "Toning Intensity", "Dials the tint alone, on top of Look Intensity. Past 1 it pushes beyond the reference. If Look Intensity is 0, so is this.", nodeone::kParamFloat, 1.0, 0.0, 2.0, 0.001, nullptr, 0, 3, 180},
    {"tone_bypass", "Bypass Toning", "Kills the tint only. Contrast and saturation stay put; the neutral axis goes perfectly grey.", nodeone::kParamBool, 0.0, 0.0, 1.0, 1.0, nullptr, 0, 3, 56},
    {"tonescale_preset", "Tonescale", "Replaces the tone curve the selected look carries. Use Look Preset leaves the look's own curve alone, which is what you want unless you are deliberately putting a different response under a look's colour. The others are named for what they measurably do, from the steepest to the softest: Punchy has the hardest foot and places grey low, Cinema places grey low with a long shoulder, Medium and Gentle ease off in that order, Soft has the longest foot and the deepest black, Low Contrast is the flattest. ACES 1.x and ACES 2.0 are the published standards, there to match a delivery that asks for them. CONTRAST is the odd one out and the only one you can leave on: instead of replacing the look's curve it tilts it, giving the look's own slope multiplied by 1.15, with 18 percent grey solved back to exactly where the look had it so your camera exposure does not move. Every other entry in this menu does move grey - Cinema and Punchy by more than half a stop, the two ACES by about a tenth - because placing grey somewhere else is part of what those curves are.", nodeone::kParamChoice, 0.0, 0.0, 9.0, 1.0, kOpt_tonescale_preset, 10, 4, 164},
    {"tone_curve_bypass", "Bypass Tone", "Return the tonescale to the one the selected look carries, ignoring the Tonescale menu above.", nodeone::kParamBool, 0.0, 0.0, 1.0, 1.0, nullptr, 0, 4, 160},
    {"trim_con", "Log Contrast", "S-curve applied to the log signal before the render, which is why its pivot reads in log. Runs ahead of the look, so it stacks on any preset, and it is not the print stock contrast of the look itself.", nodeone::kParamFloat, 0.0, -0.5, 1.0, 0.0001, nullptr, 0, 5, 120},
    {"trim_piv", "Pivot", "The pivot, absolute and readable. 0.336 is 18 percent grey, so grey holds while you turn Contrast. One stop down is 0.267, one up 0.407, diffuse white 0.514. Idle while Contrast is 0.", nodeone::kParamFloat, 0.336, 0.0, 1.0, 0.001, nullptr, 0, 5, 124},
    {"trim_ovl", "Overlay", "The Overlay composite mode of a node blended onto itself, ported from NODE_Composite2. Because source and backdrop are the same pixel it becomes a pure S-curve, and it runs in LOG, where its pivot sits about 2.3 stops above grey - so it bites into the top of the midtones rather than around grey, which is what gives it a different character from Log Contrast. Negative runs the operation backwards. It carries the chroma-gain limiter from the original: the operator works channel by channel, so it multiplies the gap between channels and therefore the chroma, and without the limiter a saturated colour lands far out of gamut for the render downstream to flatten. It is drawn on the Curve View, because unlike the highlight trims it does move a neutral.", nodeone::kParamFloat, 0.0, -1.0, 1.0, 0.001, nullptr, 0, 5, 128},
    {"trim_sh", "Shadows", "Reopens the bottom of the curve. A gain above the black floor, not an offset: black stays black, no milky veil, no hue drift. Grey and white do not move.", nodeone::kParamFloat, 0.0, -1.0, 1.0, 0.001, nullptr, 0, 5, 132},
    {"trim_hp", "Highlight Purity", "Path to white: how fast saturated highlights lose their hue. Up keeps neons, skies and fire coloured further. Hue bleached here cannot be recovered downstream. Not drawn on the Curve View, and that is measured rather than assumed: the plot traces a NEUTRAL ramp, and over 15 stops this control moves a neutral by at most 0.0005 - half a 10-bit code, thinner than the line itself. On saturated content it moves the picture by 0.31. It is a colour control, so the place to watch it is the picture, not the curve.", nodeone::kParamFloat, 0.0, -1.0, 1.0, 0.001, nullptr, 0, 5, 136},
    {"trim_hd", "Highlight Density", "The partner to Highlight Purity, and it works on the other half of the problem. Purity decides how much COLOUR a bright pixel keeps; this decides how much LIGHT it carries - and light is what the colour needs somewhere to live in. Hold a saturated sky at full purity and its strongest channel pins at 1.000: the colour is there, the gradation is gone, and the highlight reads as a flat slab. Adding density lowers that highlight, the pinned channel comes off the ceiling, and the shape inside it comes back. It is what a dye layer does - a saturated colour on film is DARKER than a neutral of the same luminance, which is exactly why film has room above a red. Scaled by how saturated the pixel is, so a neutral highlight is never touched, and confined to the top of the scale, so it cannot reach into the midtones. The slider only ADDS density, from nothing to a stop and a third. It does not go the other way on purpose: lifting a saturated highlight pushes it into the ceiling, and a gain that fades as it approaches that ceiling makes the picture go DARKER as the light rises - measured at 233 times the surrounding curvature, which is the very defect this control exists to repair. Use Brilliance if you want a saturated highlight to sit higher. Not drawn on the Curve View, and here the reason is exact rather than small: the gain is scaled by the scene saturation, which is identically zero on a neutral - measured at 1.8e-07 over 15 stops, pure float noise - while the same setting moves saturated content by 0.24. There is literally nothing to plot.", nodeone::kParamFloat, 0.0, 0.0, 1.0, 0.001, nullptr, 0, 5, 140},
    {"trim_hs", "Highlight Saturation", "Colour in the upper midtones and the lower highlights - and it is not another Highlight Purity. Measured on a saturated orange climbing through the scale: this one peaks around four and a half stops over and then EASES, so the very top still goes to white, and it costs almost no lightness doing it. Highlight Purity instead climbs all the way and holds the top back from white, which is its job, and costs seven times more lightness. Right makes a bright colour stay a colour instead of turning pale as it brightens. Left is the same axis the other way: the colour gives way earlier and more gently on the way up, for a creamy shoulder, the way an older print behaves. The top reaches white either way. Not drawn on the Curve View: measured over 15 stops it moves a neutral by 0.0004, well under half a 10-bit code, against 0.22 on saturated content.", nodeone::kParamFloat, 0.0, -1.0, 1.0, 0.001, nullptr, 0, 5, 148},
    {"trim_br", "Brilliance", "Lightness of saturated colour, neutrals untouched. Up stops saturated reds going black, down adds density. Mostly reds, oranges and magentas. Not drawn on the Curve View: measured over 15 stops it moves a neutral by 0.0007, half a 10-bit code, against 0.03 on saturated content.", nodeone::kParamFloat, 0.0, -1.0, 1.0, 0.001, nullptr, 0, 5, 144},
    {"trim_mp", "Mid Purity", "Colour density of the midtones, where skin, foliage and skies live - and the only trim that works in the scene, alongside Color Weight and Color Density. It scales chroma in the DENSITY domain, anchored on the channel carrying the LEAST dye: that channel stays where it is and the others gain density, which is what a purer set of dyes actually does. So a colour DARKENS slightly as it enriches, about nine ten-bit codes at full travel on skin - that is the behaviour, not a side effect, and it is the same thing Color Weight does on purpose. The anchor is not a detail: an earlier version preserved the mean level instead, which sounds cleaner but means lowering the weak channel RAISES the other two, and the render divides by a norm those two dominate, so the weak channel took the same correction twice. Measured at equal rendered chroma it broke ramps at 1.30 percent against 0.83 for the Chroma slider - worse than a control already shipping, for the same result. Anchored on the strongest channel there is only one effect, and it is the same model Chroma uses, so the two handle alike. On a neutral all three densities are equal, so there is nothing to scale: a grey cannot move at any setting - measured at 2e-08 over the whole range, which is float noise. Because it sits in the scene, the tonescale and the path to white then RESPOND to what it puts down - you get an emulsion that carried more dye through the midrange, not a saturation pasted onto a render that has already decided. Right enriches, left goes pastel and the midrange turns chalky in a way a faded print does. The band is read on exposure relative to 18 percent grey with the same anchor Color Density uses, so it falls in the same place on all eight looks, and it is exactly zero beyond three and a half stops from its pivot - it cannot reach where Highlight Purity and Highlight Density work, so it never argues with them. What it cannot do is make a badly behaved look behave: on saturated foliage, sky and cyan the print looks break a ramp on their own, measured at 3.3 percent with every control at zero, and any control that adds chroma shows that up - this one at 4.8 percent worst case against 4.1 for Chroma. The limit there is the look, not the slider. Not drawn on the Curve View: a neutral has no chroma to scale, so there is nothing to plot.", nodeone::kParamFloat, 0.0, -1.0, 1.0, 0.001, nullptr, 0, 5, 152},
    {"trim_mp_pv", "Mid Purity Pivot", "Where Mid Purity acts, in stops above or below 18 percent grey. Aim it: foliage and shadowed skin sit around one to two stops under, lit faces around half a stop under to grey, open sky and bright cloth one to two stops over. At 0 the band is centred on grey and spans three and a half stops either side, which covers the midrange as a whole - move it only when you want one of those things and not the others. Does nothing on its own; it only places Mid Purity.", nodeone::kParamFloat, 0.0, -2.0, 2.0, 0.001, nullptr, 0, 5, 156},
    {"trim_bypass", "Bypass Trims", "Switch all six trims off in one click, to compare the trimmed picture against the look as it comes.", nodeone::kParamBool, 0.0, 0.0, 1.0, 1.0, nullptr, 0, 5, 116},
    {"trim_reset", "Reset Trims", "Returns every control in this group to its default in one click, as a single undo step. It reads the group itself rather than a hand-written list, so a control added here later is reset too without anyone having to remember. It does not touch anything outside the group - Color, White and the look are left exactly as they are.", nodeone::kParamPush, 0.0, 0.0, 100.0, 0.1, nullptr, 0, 5, nodeone::kNoOffset},
    {"wb_preset", "Illuminant", "Which light the scene was actually lit by. Native is a true bypass - no correction at all, not a correction that happens to cancel. Anything else declares the illuminant, and the picture is adapted from it to the working space's own white with a Bradford transform. Pick the entry, or leave it on Native and dial Kelvin by hand below.", nodeone::kParamChoice, 0.0, 0.0, 17.0, 1.0, kOpt_wb_preset, 18, 6, 60},
    {"wb_kelvin", "Kelvin", "The illuminant in Kelvin, read by hand rather than picked from the list. It only takes over when Illuminant is on Native. 6504 is the working space's own white, so leaving it there is an exact bypass in every space rather than a small parasitic drift.", nodeone::kParamFloat, 6504.0, 1800.0, 20000.0, 1.0, nullptr, 0, 6, 64},
    {"wb_temp", "Temp", "Fine trim on the illuminant, in MIRED rather than in Kelvin - which is why it feels even in both directions where a Kelvin trim does not: 100 K at 3200 K is a visible move and 100 K at 10000 K is nothing, while a mired is a mired everywhere. Full travel is 60 mired, so from 6504 K it reaches about 4700 K one way and about 10600 K the other. It was 300 mired in NODE_WB, which sounds stronger and was in fact WEAKER: from 6504 K the positive half hit the 25000 K wall at 0.38 of the travel, so three fifths of that side of the slider was the same picture.", nodeone::kParamFloat, 0.0, -1.0, 1.0, 0.001, nullptr, 0, 6, 68},
    {"wb_tint", "Tint", "Green / magenta, across the locus rather than along it - so it moves the white in the one direction Kelvin cannot reach. Full travel is 0.012 Duv. It was 0.025 in NODE_WB, which at low Kelvin pushed the white point outside the CIE triangle, where the adaptation degenerates and the safety floor has to clamp the gain; at 0.012 the whole travel stays in the well-behaved region at any usable Kelvin. The direction is taken on the PLANCKIAN locus, which is how Duv is defined and which also fixes a measured fault: taken on the blended locus, the tint axis was 42.8 degrees off at 4000 K and negative tint went blue-magenta instead of magenta.", nodeone::kParamFloat, 0.0, -1.0, 1.0, 0.001, nullptr, 0, 6, 72},
    {"wb_bypass", "Bypass Illuminant", "Switches the whole illuminant block off - preset, Kelvin, Temp and Tint together - without touching any of their values. It leaves Creative White below it alone, so you can A/B the white balance against the creative whitepoint separately.", nodeone::kParamBool, 0.0, 0.0, 1.0, 1.0, nullptr, 0, 6, 76},
    {"_cwp", "Creative White", "Set the creative whitepoint of the display peak luminance. With D65 all channels are equal. With D50, the peak luminance value will match a D50 whitepoint. This can be creatively desireable. This adjustment is applied post-tonescale.", nodeone::kParamChoice, 4.0, 0.0, 4.0, 1.0, kOpt__cwp, 5, 6, 84},
    {"_cwp_rng", "Creative White Range", "The intensity range affected by the Creative White adjustment. At 1.0, the entire intensity range is affected. As Range is decreased, more of midtones and shadows are left unaffected. It can be creatively desireable to keep midtones more neutral while shifting highlights warmer.", nodeone::kParamFloat, 0.5, 0.0, 1.0, 0.001, nullptr, 0, 6, 88},
    {"cw_bypass", "Bypass Creative White", "Switch the creative white point off and return to D65, the calibrated neutral of the display.", nodeone::kParamBool, 0.0, 0.0, 1.0, 1.0, nullptr, 0, 6, 80},
    {"col_chroma", "Chroma", "Overall colour intensity, applied at the very end of the render on the distance from the achromatic axis. At 1.00 the render is untouched. At 0 the picture is monochrome. It scales what the transform has already decided rather than feeding more saturation into it, so pushing it up cannot drive a colour back outside the display. The travel runs 0 to 2 so that 1.00 - no change - sits in the MIDDLE of the slider rather than at three quarters: the same drag distance now buys the same amount of change in either direction, and there is as much room to push as to pull.", nodeone::kParamFloat, 1.0, 0.0, 2.0, 0.001, nullptr, 0, 7, 104},
    {"col_ptw", "Path To White", "How completely colour gives way as a pixel approaches peak output. 1.00 keeps the amount the selected look asks for, which is what a real medium does: no film holds saturation at peak, because peak IS white. Lower it and bright saturated light stops giving way, which clips into flat slabs of primary - useful deliberately, rarely by accident. It now works in BOTH directions: 1.00 is the look untouched, below it holds colour back from going white, above it bleaches further than the look ever would. Before, the default sat at the very end of the travel and the control could only subtract. Measured on a red at +5 stops, saturation runs 0.90 at 0.00, 0.56 at 1.00 and 0.25 at 2.00. It is an exponent rather than a mix, so 1.00 is the exact identity and there is no clip anywhere on the travel - the clipped form is what cost Highlight Purity a 241x break on blue before it was rebuilt the same way.", nodeone::kParamFloat, 1.0, 0.0, 2.0, 0.001, nullptr, 0, 7, 108},
    {"col_onset", "White Onset", "Shifts WHERE the path to white begins, without changing how much of it there is. 0.00 leaves the look's own onset. Negative starts it earlier, for a softer and more forgiving highlight; positive starts it later, holding colour closer to the top - which is what keeps neon tubes and LED practicals from going pastel a couple of stops over. The shift is a RATIO now, not a sum, and that fixed a dead half: with the looks' own onset sitting between 0.17 and 0.44, the old additive form hit its floor by -0.15, so on Default everything below that was the same picture - measured at 0.866 for both -0.50 and -0.25, digit for digit. In ratio there is no wall: the factor runs from x1.74 to x0.57 and the highest of the eight looks still lands well inside. Measured on a sky at +3 stops, saturation now runs 0.693 / 0.634 / 0.560 / 0.482 / 0.406 across the travel - five distinct curves.", nodeone::kParamFloat, 0.0, -0.5, 0.5, 0.001, nullptr, 0, 7, 112},
    {"col_weight", "Color Weight", "The darkening that comes with colour, ported from NODE_CHROMADRIVE. In a subtractive process laying down dye DARKENS: a saturated colour is not as bright as a neutral of the same hue, and a photometric render alone never says so. Driven by the chroma itself, measured in the log density plane. It fades out in the deep shadows, and that is physics rather than caution - a negative cannot build density below its own base fog. A neutral has zero chroma by construction, so no grey can move at any setting: that is algebra, not a preserve-neutrals switch.", nodeone::kParamFloat, 0.0, 0.0, 1.0, 0.001, nullptr, 0, 7, 92},
    {"col_dens", "Color Density", "Contrast in the density domain, with no colour term at all - ported from NODE_CHROMADRIVE, where it earns its own control for exactly that reason. Odd and bounded: below grey the shadows deepen, above it the highlights lift, and it is EXACTLY zero at 18 percent grey so the pivot cannot drift. The shape is its own safety - it saturates at 0.70 stop however extreme the exposure gets, so no separate ceiling is needed. Negative runs it backwards, which the original did not offer. It is not the same tool as Log Contrast: that one shapes the code values through an S-curve, this one shifts density in stops, so it keeps its slope where a log S-curve is already flattening. Measured on this engine, its shadow half is the stronger one: at -1.00 it lifts -6 stops by 1.83 stop but only pulls +6 stops down by 0.05, because the render's own shoulder has already flattened the top before this can reach it. That is honest behaviour for a density control rather than a fault, and it tells you where to reach instead - Brilliance and Highlight Density are the highlight tools.", nodeone::kParamFloat, 0.0, -1.0, 1.0, 0.001, nullptr, 0, 7, 96},
    {"col_bypass", "Bypass Color", "Switch the Color group off and return to what the selected look asks for.", nodeone::kParamBool, 0.0, 0.0, 1.0, 1.0, nullptr, 0, 7, 100},
    {"crv_enable", "Curve View", "Draws a visualization of the tonescale curve. A semi-log plot over ~ -0.005 to 128, with display encoding added.", nodeone::kParamBool, 0.0, 0.0, 1.0, 1.0, nullptr, 0, 8, 24},
    {"crv_size", "Curve Size", "Shrinks the Curve View plot towards the centre of the frame, to fit it inside the picture when the format carries black bars. Line thickness is in pixels, so it stays as fine. No effect on the render.", nodeone::kParamFloat, 1.0, 0.2, 1.0, 0.01, nullptr, 0, 8, 28},
    {"fc_overlay", "False Color", "Replaces the picture with exposure zones, read from the SCENE before any rendering - so it tells you what the camera gave you, not what the look did with it. It does not paint every stop: everything outside a decision zone stays a plain grey ramp, so you keep reading the frame, and only the four things worth a decision get a colour. GREEN is 18 percent grey, PINK is where skin should fall, YELLOW is one stop under the clip, RED is clipped. BLUE and VIOLET at the bottom mark deep shadow and crushed black. The legend down the left shows every stop with its own colour, so it cannot disagree with the image. Turn it OFF before you render.", nodeone::kParamBool, 0.0, 0.0, 1.0, 1.0, nullptr, 0, 8, 32},
    {"skin_check", "Skin Check", "Paints skin by how far it sits off the vectorscope's skin tone line, and reads exactly like the scope: YELLOW means on the line, GREEN that the tone has gone too green or too cool, MAGENTA too magenta or too warm, and the stronger the paint the further off it is. The face keeps its modelling under the paint, so you can see WHICH part of it is drifting instead of a flat sticker. Only colours that could plausibly be skin are painted - too little chroma, too much chroma or too little light and the pixel is left alone, so a red dress or a bowl of fruit does not come up as a face. The bar along the bottom is the same scale as the paint, with a white tick on the line. Turn it OFF before you render.", nodeone::kParamBool, 0.0, 0.0, 1.0, 1.0, nullptr, 0, 8, 36},
    {"legend", "Legend", "Draws the legend of whichever scope is on - the exposure zones for False Color, the four steps of the scale for Skin Check. One switch for both: they are never both on, and having to remember which checkbox belonged to which scope was the sort of thing you only discover while hunting for it. Turn it off once you know the scale and want the whole frame back.", nodeone::kParamBool, 1.0, 0.0, 1.0, 1.0, nullptr, 0, 8, 40},
    {"credits", "Credits", "MODIFIED version of OpenDRT v1.0.1 by Jed Smith, licensed GPLv3. All credit for the image rendering is his. The seven looks are OpenDRT parameter values fitted against reference LUTs generated with spektrafilm by Andrea Volpato, CC BY-SA 4.0. No LUT data is embedded. Selling this is allowed; closing it is not - any redistribution must stay GPLv3 with source. Full attribution in NOTICE.txt.", nodeone::kParamChoice, 0.0, 0.0, 9.0, 1.0, kOpt_credits, 10, -2, 168},
};
static const char* const kAbout[] = {"NODE_DRT by Samuel Drouin.", "Modified OpenDRT v1.0.1 by Jed Smith, licensed GPLv3 — github.com/jedypod/open-display-transform. The rendering engine is his work; this plugin is a modified version and is distributed under the same licence, source included.", "Look presets fitted against spektrafilm references by Andrea Volpato, CC BY-SA 4.0 — github.com/andreavolpato/spektrafilm. No LUT data is embedded; what remains are fitted parameter values.", "Subtractive saturation model by Nikita Petrovich, MIT licence — the Chroma control in the Color group. See MIT-SubtractiveSaturation.txt.", "OpenFX support library: Academy Software Foundation, BSD 3-Clause.",  nullptr};
static_assert(sizeof(DctlParams) == 184, "parameter block size");
static_assert(offsetof(DctlParams, in_gamut) == 0, "offset of in_gamut");
static_assert(sizeof(DctlParams::in_gamut) == 4 && ::dctl::is_same<decltype(DctlParams::in_gamut), int>::value, "type of in_gamut");
static_assert(offsetof(DctlParams, in_oetf) == 4, "offset of in_oetf");
static_assert(sizeof(DctlParams::in_oetf) == 4 && ::dctl::is_same<decltype(DctlParams::in_oetf), int>::value, "type of in_oetf");
static_assert(offsetof(DctlParams, tn_Lp) == 8, "offset of tn_Lp");
